\documentclass{article}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{geometry}
\geometry{a4paper, margin=1in}

\begin{document}

\begin{figure}[ht]
\centering
\begin{tikzpicture}
\begin{axis}[
    width=0.8\textwidth,
    height=0.6\textwidth,
    ybar,
    bar width=15pt,
    ymajorgrids=true,
    grid style=dashed,
    ylabel={数量（万）},
    xlabel={年份},
    symbolic x coords={2021年,2022年,2023年,2024年,2025年,2026年},
    xtick=data,
    nodes near coords,
    nodes near coords align={vertical},
    every node near coord/.style={
        font=\small,
        yshift=-8pt,
        rotate=90
    },
    enlarge x limits=0.15,
    ymin=0,
    ymax=500,
    title={2021-2026年数据统计},
    legend style={
        at={(0.5,-0.15)},
        anchor=north,
        legend columns=-1
    }
]

% 添加柱状图数据
\addplot[fill=blue!50] coordinates {
    (2021年, 377)
    (2022年, 457)
    (2023年, 474)
    (2024年, 438)
    (2025年, 388)
    (2026年, 343)
};

\legend{数据值}

\end{axis}
\end{tikzpicture}
\caption{2021-2026年数据柱状图展示}
\end{figure}

